script:
frappe.ui.form.on('Email Template', {
  refresh(frm) {
    insert_preview_container(frm);
    update_preview(frm);
  },
  response_html(frm) {
    update_preview(frm);
  }
});

// Step 1: create once, above response_html field
function insert_preview_container(frm) {
  if (frm._preview_div) return;

  // locate response_html wrapper
  const resp_wrapper = frm.fields_dict.response_html.$wrapper;
  const container = document.createElement('div');
  container.id = 'email_preview_container';
  Object.assign(container.style, {
    padding: '12px',
    border: '1px solid #ccc',
    marginBottom: '8px',
    borderRadius: '4px'
  });

  resp_wrapper[0].insertAdjacentElement('beforebegin', container);
  frm._preview_div = container;
}

// Step 2: populate the preview
function update_preview(frm) {
  if (!frm._preview_div) return;

  const html = frm.doc.response_html || frm.doc.response || '';
  frm._preview_div.innerHTML = html;
}
